//! The CrawlerGym fixture catalog.
//!
//! Static fixtures live in `fixtures/<id>/` and are embedded by `build.rs`; `s1`
//! (the static site) is generated by [`s1`] because its link graph, sitemap and
//! robots rules are the ground truth of the URL-plane counters, `g32` (the
//! security-crawl-maze reproduction) by [`crawl_maze`] because its cases need response
//! headers, nested paths and non-HTML bodies, and `d2` (the differential site) by [`d2`]
//! because its pages need redirects, per-host `robots.txt` rules and per-page delays.

pub mod backend;
pub mod crawl_maze;
pub mod d2;
pub mod s1;

/// A servable file of a fixture.
#[derive(Clone, Copy, Debug)]
pub struct FileDef {
    /// File name inside the fixture directory (`index.html`, `invoice.html`).
    pub name: &'static str,
    /// MIME type sent as the `Content-Type` header, derived from the file extension by `build.rs`.
    pub content_type: &'static str,
    /// Template source; see [`render`].
    pub body: &'static str,
}

/// An embedded fixture.
#[derive(Clone, Copy, Debug)]
pub struct FixtureDef {
    /// Fixture id; equals the directory name under `fixtures/` and the first URL path segment (`/<id>/...`).
    pub id: &'static str,
    /// Raw JSON text of the fixture's `manifest.json`, parsed on demand into a `Manifest`.
    pub manifest_json: &'static str,
    /// Servable files (html/js/css/json/svg/txt) of the fixture, sorted by name; `manifest.json` is excluded.
    pub files: &'static [FileDef],
}

include!(concat!(env!("OUT_DIR"), "/fixtures_gen.rs"));

