/// Behavior-family names (`hybrid-mix`, `shared-workspace`, ...) to the fixture id.
pub const NAMED_FIXTURES: [(&str, &str); 5] = [
    ("hybrid-mix", "hybrid-mix"),
    ("async-late", "async-late"),
    ("one-button-n-behaviors", "g22"),
    ("query-identity", "g12"),
    ("shared-workspace", "g20"),
];

/// Fixture id implementing catalog row `row` (`"G22"`).
#[must_use]
pub fn catalog_row(row: &str) -> Option<&'static str> {
    CATALOG_ROWS
        .iter()
        .find(|(r, _)| r.eq_ignore_ascii_case(row))
        .map(|(_, id)| *id)
}

/// Every embedded fixture, sorted by id.
#[must_use]
pub fn all() -> &'static [FixtureDef] {
    GENERATED
}

/// The fixture with this id.
#[must_use]
pub fn find(id: &str) -> Option<&'static FixtureDef> {
    GENERATED.iter().find(|d| d.id == id)
}

impl FixtureDef {
    /// Resolve a path inside the fixture (`""` is `index.html`; `invoice` finds `invoice.html`).
    #[must_use]
    pub fn file(&self, rest: &str) -> Option<&'static FileDef> {
        let rest = rest.trim_start_matches('/');
        let rest = if rest.is_empty() { "index.html" } else { rest };
        self.files.iter().find(|f| f.name == rest).or_else(|| {
            self.files
                .iter()
                .find(|f| f.name.strip_suffix(".html").is_some_and(|stem| stem == rest))
        })
    }
}

/// Expand the template placeholders of a fixture file.
///
/// `{{GYM_JS}}` becomes the shared client library in a `<script>` element; `{{SEED}}`,
/// `{{FIXTURE}}` and `{{BASE}}` are plain substitutions. Order matters: the library itself
/// contains `{{SEED}}` and `{{FIXTURE}}`.
#[must_use]
pub fn render(body: &str, fixture: &str, seed: u64, base: &str) -> String {
    let lib = format!("<script>\n{GYM_JS}\n</script>");
    body.replace("{{GYM_JS}}", &lib)
        .replace("{{SEED}}", &(seed & 0xFFFF_FFFF).to_string())
        .replace("{{FIXTURE}}", fixture)
        .replace("{{BASE}}", base.trim_end_matches('/'))
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
    use super::*;

    #[test]
    fn render_expands_nested_placeholders() {
        let out = render(
            "<head>{{GYM_JS}}</head>{{BASE}}/{{FIXTURE}}/{{SEED}}",
            "g01",
            7,
            "http://h:1/",
        );
        assert!(out.contains("var SEED = 7 >>> 0;"), "{out}");
        assert!(out.contains("var FIXTURE = 'g01';"));
        assert!(out.ends_with("http://h:1/g01/7"));
        assert!(!out.contains("{{"));
    }

    #[test]
    fn catalog_has_every_assignment_fixture() {
        for id in CATALOG_IDS {
            let def = find(id).unwrap_or_else(|| panic!("fixture {id} missing"));
            if id != "s1" && id != "d2" {
                assert!(def.file("").is_some(), "{id} has no index.html");
            }
        }
        assert_eq!(
            all().len(),
            CATALOG_IDS.len(),
            "unexpected extra fixture directories"
        );
    }

    #[test]
    fn file_lookup_accepts_stems_and_names() {
        let def = FixtureDef {
            id: "x",
            manifest_json: "{}",
            files: &[
                FileDef {
                    name: "index.html",
                    content_type: "text/html",
                    body: "i",
                },
                FileDef {
                    name: "invoice.html",
                    content_type: "text/html",
                    body: "v",
                },
            ],
        };
        assert_eq!(def.file("").unwrap().body, "i");
        assert_eq!(def.file("invoice").unwrap().body, "v");
        assert_eq!(def.file("invoice.html").unwrap().body, "v");
        assert!(def.file("nope").is_none());
    }
}
